760	/**
761	 * Fetch a single session by ID.
762	 * AC: @ui-session-stream ac-4
763	 */
764	export async function fetchSession(id: string): Promise<SessionDetail> {
765		if (isStaticMode()) {
766			throw new Error('Session data not available in static mode');
767		}
768	
769		const response = await fetch(`${API_BASE}/api/sessions/${id}`, {
770			headers: getProjectHeaders()
771		});
772		if (!response.ok) {
773			await handleResponseError(response);
774		}
775	
776		return response.json();
777	}
778	
779	/**
780	 * Fetch session events (optionally incremental via since_seq).
781	 * AC: @ui-session-stream ac-1, ac-2
782	 */
783	export async function fetchSessionEvents(
784		id: string,
785		sinceSeq?: number
786	): Promise<{ events: SessionEvent[]; total: number }> {
787		if (isStaticMode()) {
788			return { events: [], total: 0 };
789		}
790	
791		const url = new URL(`${API_BASE}/api/sessions/${id}/events`);
792		if (sinceSeq !== undefined) {
793			url.searchParams.set('since_seq', String(sinceSeq));
794		}
795	
796		const response = await fetch(url.toString(), {
797			headers: getProjectHeaders()
798		});
799		if (!response.ok) {
800			await handleResponseError(response);
801		}
802	
803		return response.json();
804	}
