814		refErrors: Array<{ source: string; ref: string; message: string }>;
815		refWarnings: Array<{ source: string; ref: string; message: string }>;
816		orphans: Array<{ type: string; ulid: string; title: string }>;
817		completenessWarnings: Array<{ item: string; message: string }>;
818		traitCycles: Array<{ cycle: string[] }>;
819	}
